  setAutoRemap(false);setWantFocus(true);setEnterBehavior(ui::PopupWindow::EnterBehavior::DoNothingOnEnter);search_=new HistorySearchEntry(font,skin);addChild(search_);search_->Change.connect([this]{sync();});category_=new PixelDropdown(font,skin);addChild(category_);std::vector<std::u32string> titles;for(const auto& d:shortcuts::catalog())if(std::find(categories_.begin(),categories_.end(),d.group)==categories_.end()){categories_.push_back(d.group);titles.push_back(d.groupLabel);}category_->setOptions(titles);const auto tools=std::find(categories_.begin(),categories_.end(),"tools");category_->setSelectedIndex(int(tools-categories_.begin()));category_->changed=[this](int){sync();};list_=new HistoryList(font,skin);list_->emptyText=U"没有匹配的快捷键";addChild(list_);list_->selected=[this](std::size_t index){if(index<shortcuts::catalog().size()){selected_=shortcuts::catalog()[index].id;sync();}};binding_=new PixelDropdown(font,skin);addChild(binding_);binding_->changed=[this](int){syncActions();};
  add_=button(U"添加",[this]{record(-1);});edit_=button(U"更改",[this]{record(binding_->selectedIndex());});remove_=button(U"移除",[this]{if(binding_->selectedIndex()>=0)shortcuts::remove(draft_,selected_,std::size_t(binding_->selectedIndex()));sync();});reset_=button(U"重置此项",[this]{shortcuts::reset(draft_,selected_);sync();});all_=button(U"全部重置",[this]{draft_=shortcuts::defaults();error_.clear();sync();});done_=button(U"完成",[this]{error_=save_(draft_);if(error_.empty())closeWindow(nullptr);else invalidate();});close_=button(U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";
  importButton_=button(U"导入",[this]{setClickBehavior(ui::PopupWindow::ClickBehavior::DoNothingOnClick);try{if(auto text=import_()){draft_=shortcuts::decode(*text);error_=U"已导入草稿，点击完成保存";sync();}}catch(const std::exception& e){error_=U"导入失败："+unicodeText(e.what());invalidate();}setClickBehavior(ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow);});exportButton_=button(U"导出",[this]{setClickBehavior(ui::PopupWindow::ClickBehavior::DoNothingOnClick);try{export_(shortcuts::encode(draft_));}catch(const std::exception& e){error_=U"导出失败："+unicodeText(e.what());invalidate();}setClickBehavior(ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow);});importButton_->iconSkin=&icons;importButton_->icon="folderOpen";importButton_->iconWithCaption=true;exportButton_->iconSkin=&icons;exportButton_->icon="export";exportButton_->iconWithCaption=true;sync();
