 void sync(){const auto query=unicodeText(search_->text());const bool searching=!shortcuts::trim(search_->text()).empty();const int group=category_->selectedIndex();std::vector<HistoryListRow> rows;for(std::size_t i=0;i<shortcuts::catalog().size();++i){const auto& d=shortcuts::catalog()[i];const auto bindings=shortcuts::format(shortcuts::forId(draft_,d.id));if(!searching&&(group<0||std::size_t(group)>=categories_.size()||d.group!=categories_[group]))continue;const auto searchable=d.label+U" "+d.groupLabel+U" "+unicodeText(d.id+" "+(bindings.empty()?"未设置":bindings));if(searching&&!historySearchMatches(searchable,query))continue;std::u32string label=d.label+U"  "+unicodeText(bindings.empty()?"未设置":bindings);const bool connected=supported_(d.id);if(!connected)label+=U"  [未迁移]";for(const auto& value:shortcuts::forId(draft_,d.id))if(!shortcuts::blockedBy(draft_,d.id,value).empty()){label+=U"  [冲突]";break;}rows.push_back({i,std::move(label),d.id==selected_,!connected,false});}list_->setRows(std::move(rows));std::vector<std::u32string> values;for(const auto& value:shortcuts::forId(draft_,selected_))values.push_back(unicodeText(value));const int previous=binding_->selectedIndex();binding_->setOptions(values);if(!values.empty())binding_->setSelectedIndex(std::clamp(previous,0,int(values.size())-1));syncActions();invalidate();}
